// Plan the Meta fetch jobs for this run. One item per (client, kind, date chunk).
//
// Schedule: the trigger fires hourly at :35 UTC (wf_meta_ads_to_bigquery runs
// at :15, ClickUp sync and plan pacing at :45).
//   every hour             ad sets, D-3..D-1
//   03,07,11,15,19,23 UTC  + age x gender and placement breakdowns, D-3..D-1
//   03 UTC (daily)         catch-up: ad sets D-35..D-1, breakdowns D-14..D-1.
//                          A client/kind with no rows in the last 40 days gets a
//                          backfill instead: ad sets D-90..D-1, breakdowns D-35..D-1.
//   manual run             behaves like the 03 UTC run
// Today is never fetched (partial day), the same rule as wf_meta_ads_to_bigquery,
// so native ad set rows and ad-level rows cover the same days.
// Every window is re-fetched in full: raw is append-only and the stg views keep
// the newest ingested_at per key, so overlap is free and gaps self-heal.
const SHORT = 3;
const ADSET_CATCHUP = 35, BRK_CATCHUP = 14;
const ADSET_BACKFILL = 90, BRK_BACKFILL = 35;
const ADSET_CHUNK = 31, BRK_CHUNK = 7;
const CATCHUP_HOUR = 3;
const BREAKDOWN_HOURS = [3, 7, 11, 15, 19, 23];

const now = new Date();
const hour = now.getUTCHours();
// Only an explicit manual run widens the windows; anything scheduled stays light.
const isManual = $execution.mode === 'test' || $execution.mode === 'manual';
const catchup = isManual || hour === CATCHUP_HOUR;
const breakdowns = catchup || BREAKDOWN_HOURS.includes(hour);

const ymd = d => d.toISOString().slice(0, 10);
const back = n => { const d = new Date(now); d.setUTCDate(d.getUTCDate() - n); return ymd(d); };
const chunks = (days, size) => {
  const out = [];
  for (let end = 1; end <= days; end += size) {
    out.push({ since: back(Math.min(end + size - 1, days)), until: back(end) });
  }
  return out;
};
const isEmpty = v => v === null || v === undefined || v === '' || v === 'null';

const jobs = [];
for (const item of $input.all()) {
  const c = item.json;
  const add = (kind, mode, ranges) => ranges.forEach(r => jobs.push({ json: {
    client_id: c.client_id, slug: c.slug, kind, mode, since: r.since, until: r.until,
    exec_mode: $execution.mode
  }}));

  if (catchup) {
    if (isEmpty(c.adset_max)) add('adset', 'backfill', chunks(ADSET_BACKFILL, ADSET_CHUNK));
    else add('adset', 'catchup', chunks(ADSET_CATCHUP, ADSET_CHUNK));
    for (const kind of ['demo', 'placement']) {
      if (isEmpty(c[kind + '_max'])) add(kind, 'backfill', chunks(BRK_BACKFILL, BRK_CHUNK));
      else add(kind, 'catchup', chunks(BRK_CATCHUP, BRK_CHUNK));
    }
  } else {
    add('adset', 'short', chunks(SHORT, SHORT));
    if (breakdowns) {
      add('demo', 'short', chunks(SHORT, SHORT));
      add('placement', 'short', chunks(SHORT, SHORT));
    }
  }
}
return jobs;

// Any failed job fails the execution, so the error workflow alerts. Rows of the
// jobs that succeeded are already in BigQuery; the next run re-fetches the rest.
const jobs = $input.all().map(i => i.json);
const failed = jobs.filter(j => Array.isArray(j.errors) && j.errors.length > 0);
if (failed.length > 0) {
  const lines = failed.slice(0, 10).map(j => j.client_id + ' ' + j.kind + ' ' + j.since + '..' + j.until + ': ' + j.errors.join(' | '));
  throw new Error(failed.length + ' of ' + jobs.length + ' Meta jobs failed. ' + lines.join(' || '));
}
return jobs.map(j => ({ json: j }));

// Secrets decoded once per job. `.first()` deliberately, never `.item`: resolving
// a paired item across a chain this wide makes n8n walk the whole execution graph.
const decode = b64 => Buffer.from(b64, 'base64').toString('utf8').trim();
const job = $('Loop over jobs').first().json;

// No action_attribution_windows on purpose: like the legacy ad-level request in
// wf_meta_ads_to_bigquery, every ad set reports on its own attribution setting,
// so native ad set purchases equal the sum of the ad rows (see migration 256).
const LEVEL = { adset: 'adset', demo: 'ad', placement: 'ad' };
const FIELDS = {
  adset: 'adset_id,adset_name,campaign_id,campaign_name,spend,impressions,reach,frequency,clicks,ctr,cpc,actions,action_values,outbound_clicks',
  demo: 'ad_id,spend,impressions,reach,clicks,actions,action_values',
  placement: 'ad_id,spend,impressions,reach,clicks,actions,action_values'
};
const BREAKDOWNS = { demo: 'age,gender', placement: 'publisher_platform,platform_position,impression_device' };

const query = {
  level: LEVEL[job.kind],
  time_increment: '1',
  time_range: JSON.stringify({ since: job.since, until: job.until }),
  fields: FIELDS[job.kind],
  limit: '500',
  access_token: decode($('Get access_token').first().json.payload.data)
};
if (BREAKDOWNS[job.kind]) query.breakdowns = BREAKDOWNS[job.kind];

return [{ json: {
  client_id: job.client_id,
  slug: job.slug,
  kind: job.kind,
  mode: job.mode,
  since: job.since,
  until: job.until,
  ad_account_id: decode($('Get ad_account_id').first().json.payload.data),
  api_version: 'v22.0',
  query_json: JSON.stringify(query)
}}];

// Meta insights rows -> raw table rows, shaped exactly like the target table
// (the BigQuery insert maps keys automatically; an extra key fails the insert).
// Emits one marker item {_empty: true} when there is nothing to insert, so the
// loop always continues to the next job.
const ctx = $('Decode secrets').first().json;
const INGESTED_AT = new Date().toISOString();
const SOURCE = ctx.mode === 'backfill' ? 'backfill' : 'cron';
// NUMERIC takes at most 9 decimals; rounding keeps a long float from failing a batch.
const dec = v => (v === null || v === undefined || v === '' ? null : Math.round(Number(v) * 1e9) / 1e9);
// INT64 must not receive 18234.0: BigQuery rejects a decimal point in an INT64.
const int = v => (v === null || v === undefined || v === '' ? null : Math.round(Number(v)));
const pick = (arr, type) => {
  if (!Array.isArray(arr)) return null;
  const row = arr.find(a => a.action_type === type);
  return row ? Number(row.value) : null;
};
const purchases = r => pick(r.actions, 'omni_purchase') ?? pick(r.actions, 'purchase');
const purchaseValue = r => pick(r.action_values, 'omni_purchase') ?? pick(r.action_values, 'purchase');
// raw_meta_adset_insights.actions / action_values are ARRAY<STRUCT<action_type STRING, value NUMERIC>>.
const structs = arr => (Array.isArray(arr) ? arr : []).map(a => ({ action_type: String(a.action_type), value: dec(a.value) }));

const input = $input.all();
const errItem = input.find(i => i.json && i.json.error);
const raw = [];
for (const it of input) {
  const j = it.json;
  if (Array.isArray(j.data)) for (const r of j.data) raw.push(r);
}

let rows;
if (ctx.kind === 'adset') {
  rows = raw.map(r => ({
    client_id: ctx.client_id,
    ingested_at: INGESTED_AT,
    ingest_source: SOURCE,
    ad_account_id: ctx.ad_account_id,
    campaign_id: String(r.campaign_id ?? ''),
    campaign_name: r.campaign_name ?? null,
    adset_id: String(r.adset_id ?? ''),
    adset_name: r.adset_name ?? null,
    date_start: r.date_start,
    date_stop: r.date_stop,
    spend: dec(r.spend),
    impressions: int(r.impressions),
    reach: int(r.reach),
    frequency: dec(r.frequency),
    clicks: int(r.clicks),
    ctr: dec(r.ctr),
    cpc: dec(r.cpc),
    purchases: int(purchases(r)),
    purchase_value: dec(purchaseValue(r)),
    add_to_cart: int(pick(r.actions, 'add_to_cart')),
    initiate_checkout: int(pick(r.actions, 'initiate_checkout')),
    landing_page_views: int(pick(r.actions, 'landing_page_view')),
    link_clicks: int(pick(r.actions, 'link_click')),
    outbound_clicks: int(pick(r.outbound_clicks, 'outbound_click')),
    actions: structs(r.actions),
    action_values: structs(r.action_values),
    payload_json: JSON.stringify(r)
  })).filter(r => r.adset_id !== '' && r.campaign_id !== '');
} else {
  // A breakdown bucket with no impressions is one Meta had nothing to say about;
  // keeping it would inflate every "which age group" denominator with zeroes.
  rows = raw.filter(r => Number(r.impressions) > 0 && r.ad_id).map(r => {
    const base = {
      client_id: ctx.client_id,
      ingested_at: INGESTED_AT,
      ad_account_id: ctx.ad_account_id,
      ad_id: String(r.ad_id),
      date_start: r.date_start,
      date_stop: r.date_stop
    };
    const dims = ctx.kind === 'demo'
      ? { age: r.age ?? 'unknown', gender: r.gender ?? 'unknown' }
      : { publisher_platform: r.publisher_platform ?? 'unknown',
          platform_position: r.platform_position ?? 'unknown',
          impression_device: r.impression_device ?? null };
    return Object.assign(base, dims, {
      spend: dec(r.spend),
      impressions: int(r.impressions),
      reach: int(r.reach),
      clicks: int(r.clicks),
      purchases: int(purchases(r)),
      purchase_value: dec(purchaseValue(r)),
      payload_json: JSON.stringify(r)
    });
  });
}

if (rows.length === 0) {
  let msg = null;
  if (errItem) {
    const e = errItem.json.error;
    msg = (typeof e === 'string' ? e : JSON.stringify(e)).slice(0, 800);
  }
  return [{ json: { _empty: true, _error: msg } }];
}
return rows.map(r => ({ json: r }));

// One summary item per job, fed back to the loop. Insert failures surface here
// because the insert nodes continue on error (one bad job must not stop the
// other clients); "Fail run on errors" then turns them into a failed execution.
const job = $('Decode secrets').first().json;
const tr = $('Transform rows').all();
const empty = tr.length === 1 && tr[0].json._empty === true;
const errors = [];
if (empty && tr[0].json._error) errors.push('fetch: ' + tr[0].json._error);
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.error) errors.push('insert: ' + (typeof j.error === 'string' ? j.error : JSON.stringify(j.error)).slice(0, 800));
  if (Array.isArray(j.insertErrors) && j.insertErrors.length) errors.push('insertErrors: ' + JSON.stringify(j.insertErrors).slice(0, 800));
}
return [{ json: {
  client_id: job.client_id, kind: job.kind, mode: job.mode,
  since: job.since, until: job.until,
  rows: empty ? 0 : tr.length,
  errors
}}];
